INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"IN_ORDER_TO_INCREASE","Со оглед на тоа што имаме за цел да ја зголемиме нашата дилерска мрежа и да го прошириме географскиот дофат на нашата дистрибуција на опрема за услуги за храна, упатуваме покана до компаниите заинтересирани да станат овластени дилери за долгорочна соработка. Нашето дилерско партнерство нуди атрактивни бенефиции, вклучително и структура на попуст, флексибилни можности за испорака и плаќање, сеопфатен пакет транспортни и логистички услуги, пристап до технички ресурси и маркетиншки колатерал. Покрај тоа, дилерите кои активно учествуваат во набавките на владини тендери се подобни за програми за поттикнување бонус кои обезбедуваат зголемени нивоа на попуст.");
