INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"IS_NOT_COUNTRY_TEXT","Земјата на другата страна не е наведена во сметководствениот систем.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"IS_NOT_COUNTRY_HELP","Нема информации за земјата на регистрација на вашата сметка во нашиот систем на сметки. Контактирајте со вашиот менаџер за да ја додели земјата на вашата друга страна.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"IS_NOT_VERIFIED_TEXT","Непотврдена е-пошта.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"IS_NOT_VERIFIED_HELP","Сè уште не сте ја потврдиле вашата е-пошта. За да ја потврдите регистрацијата, кликнете на врската во е-поштата што ви е испратена по регистрацијата. Проверете ги дојдовните пораки и папката Спам. Можете исто така да побарате врска за потврда повторно; Ве молиме одете на страницата:");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"IS_NOT_CONFIRMED_DIRECTOR_TEXT","Сметката е деактивирана од вашиот претпоставен.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"IS_NOT_CONFIRMED_DIRECTOR_HELP","Вашата сметка е деактивирана. За повеќе информации, контактирајте го вашиот претпоставен.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"IS_NOT_PORTAL_CONFIRMER_TEXT","Сметката не е потврдена од менаџерот.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"IS_NOT_PORTAL_CONFIRMER_HELP","Вашата регистрација е забележана, а нашиот менаџер е во процес на потврда за да ви овозможи целосен пристап до порталот. Ве молиме почекајте ја оваа потврда. Ако сакате да го забрзате процесот, можете директно да контактирате со вашиот менаџер.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"IS_NOT_ACTIVE_TEXT","Сметката е деактивирана.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"IS_NOT_ACTIVE_HELP","Вашата сметка е деактивирана. За повеќе информации, контактирајте со вашиот менаџер.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"IS_NOT_ENTITY_TEXT","Нема правно лице наведено во нашиот сметководствен систем.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"IS_NOT_ENTITY_HELP","Во моментов немаме информации за вашето правно лице во нашиот сметководствен систем. Ако сте нова договорна страна и неодамна сте потпишале договор, имајте предвид дека оваа информација може да потрае до еден ден за да се појави во нашиот систем. Ако известувањето опстојува надвор од оваа временска рамка, ве молиме контактирајте го вашиот менаџер за да го решите овој проблем.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"IS_NOT_PRICELIST_TEXT","Во нашиот сметководствен систем не е доделен ценовник.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"IS_NOT_PRICELIST_HELP","Нема информации за условите на вашиот дилер во нашиот сметководствен систем. Ве молиме стапете во контакт со вашиот менаџер за да ви биде доделен ценовник на вашата сметка.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"YOUR_ACCOUNT_HAS_ERRORS","Има грешки во вашата сметка.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"SHOW_MORE","Прикажи повеќе");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PORTAL_MENU_API","API-и");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"IS_NOT_ACTIVE_DEALER_TEXT","Договорната страна е моментално деактивирана во нашиот сметководствен систем.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"IS_NOT_ACTIVE_DEALER_HELP","Вашата сметка на другата страна е деактивирана. За повеќе детали, ве молиме контактирајте со вашиот менаџер.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"IS_NOT_SALES_TYPES_TEXT","Во нашиот сметководствен систем не е наведена насока за продажба.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"IS_NOT_SALES_TYPES_HELP","Насоката за продажба за вашата сметка не е наведена во нашиот сметководствен систем. Ве молиме контактирајте со вашиот менаџер за да ѝ доделите насока за продажба на вашата договорна страна.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"DEALERS_API_DOC","Документација за API на дилери");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"API_SUPERVISOR_ROLE_REQUIRED","За да генерирате клуч API, мора да имате сметка со улогата „Supervisor“. Ако вашата компанија моментално нема таква сметка, ве молиме контактирајте го вашиот менаџер. Алтернативно, ако треба само да креирате клуч API за идна употреба и вашата компанија веќе има сметка „Супервизор“, ве молиме стапете во контакт со сопственикот на сметката.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"API_API_KEY_WARNING","Со генерирање и користење на клучот API, го потврдувате вашиот договор со условите за користење. Сите барања направени со вашиот API клуч ќе ви се припишат вам. Имајте предвид дека генерирањето на нов API клуч ќе ги деактивира сите претходно креирани клучеви. Ќе биде неопходно да се ажурира клучот во сите системи што го користат.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"IS_NOT_ENTITY_FOR_PRICES","Нашиот сметководствен систем нема регистрирано правно лице. За да се добие пристап до ценовниците, потребно е активно правно лице. Ве молиме контактирајте со вашиот менаџер за да го поправи овој проблем.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"LINKS_TO_PRICE_BACKWARD","Врски до ценовници со компатибилност наназад");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"ATTENTION_DIRECT_LINKS","„Забележете! Врските за директно преземање го содржат вашиот API клуч во нешифрирана форма. Не споделувајте ги овие врски јавно или со никој друг освен технички специјалисти вклучени во интеграцијата на каталогот. Споделувањето на вашиот клуч овозможува пристап до процесирање трансакции и пратки во име на вашето правно лице. \"");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"IF_FOR_SOME_REASON_NEW_LINKS","Доколку новите врски за преземање ценовници не се соодветни поради која било причина, можете да ги користите врските дадени во табелата подолу. Форматот и содржината на овие стари ценовници се целосно конзистентни со она што ви е познато. Сепак, имајте предвид дека старите ценовници не нудат можност за избор на стоки врз основа на достапноста, исклучување на ДДВ од цената на чинење на стоката или земајќи ги предвид персонализираните услови од договорот на вашето правно лице. Ако сакате да ги користите овие нови функционалности, ве молиме погледнете ги опциите подолу.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICE_RANGE","Опсег");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICE_FILE_TYPE","Тип на датотека");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICE_CONTENT","Содржини");
