INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICE_FULL_UNLOADING","Целосно истоварување");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICE_FULL_UNLOADING_TEXT","Дизајниран за визуелно пребарување на потребните информации за цените на артиклите и моменталната достапност во магацините.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICE_DEALERSHIP","Дилери");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICE_RETAIL_PRICE","Малопродажна цена");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICE_FULL_YML_TEXT","Вклучува сеопфатни детали за ставката, вклучително и приспособен формат за опис на производот (vendor.model).");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICE_FULL_RETAIL_CSV_TEXT","<p>Содржи <b>максимални</b> информации за производот што се достапни во приспособен тип на опис (vendor.model). Тип на цена - <b>препорачана малопродажба</b>.</p>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICE_FULL_SUPERVIP_CSV_TEXT","<p>Содржи <b>максимални</b> информации за производот што се достапни во приспособен тип на опис (vendor.model). Тип на цена - <b>дилер</b>.</p>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICE_LITE_RETAIL_CSV_TEXT","<p>Содржи <b>минимални</b> информации за производот, кои се достапни во приспособен тип на опис (vendor.model). Тип на цена - <b>препорачана малопродажба</b>.</p>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICE_LITE_RETAIL_YML_TEXT","<p>Содржи <b>минимални</b> информации за производот што се достапни во поедноставен тип на опис. Тип на цена - <b>препорачана малопродажба</b>.</p>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICE_LITE_SUPERVIP_CSV_TEXT","<p>Содржи <b>минимални</b> информации за производот, кои се достапни во приспособен тип на опис (vendor.model). Тип на цена - <b>дилер</b>.</p>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICE_LITE_SUPERVIP_YML_TEXT","<p>Содржи <b>минимални</b> информации за производот што се достапни во поедноставен тип на опис. Тип на цена - <b>дилер</b>.</p>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICE_TO_GET_DIRECT_LINK","Мора да имате сметка со улогата „Супервизор“ за да добиете директни врски за преземање ценовници. Ако немате сметка со оваа улога, контактирајте со вашиот менаџер. Ако ви треба само да добиете директни врски за нејзино понатамошно користење и вашата компанија има сметка „Supervisor“, контактирајте со нејзиниот сопственик.");
