INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICE_ATTENTION_DIRECT_LINK","Забележете! Директните врски за преземање го содржат вашиот API клуч во нешифрирана форма. Не споделувајте ги овие врски јавно или со никој друг освен технички специјалисти вклучени во интеграцијата на каталогот. Споделувањето на вашиот клуч овозможува пристап до процесирање трансакции и пратки во име на вашето правно лице.");
