INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_AVAIL","Достапност на залиха. Ги зема вредностите <b>true</b> доколку производот е достапен во наведениот магацин, во спротивно <b>неточно</b>.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_DESC"," Опис на производотнудење.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_PURCHASE_TYPE","Тип на набавка. Може да земе вредности:<br/> <ul> <li><b>„на залиха“</b> - артиклот е на залиха барем во еден од избраните складишта</li> <li><b>“ на пат'</b> - предметот е во најблиската испорака до магацинот во Москва</li> <li><b>'на барање'</b> - стоката може да се донесе во складот во Москва на барање. <b>Посебни услови за плаќање</b> - проверете кај менаџерот.</li> </ul>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_DELIVERY_TIME","Времето на испорака на артиклите по барање до магацинот во Москва се мери во денови и може да варира во одредени вредности:<br> <ul> <li><b>број (денови)</b></li> <li> <b>'повеќе не е достапно'</b> - испораките се запрени,</li> <li><b>'проверете'</b> - проверете кај менаџерот,</li> <li>празна линија - ако времето за испорака не е дефинирано</li> </ul>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_VENDOR","Производител или бренд (заштитен знак).");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_COUNTRY","Земја на потекло на предметот.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_CODE_1C","Код за понуда на производи.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_SUPPLYDATE","Следен датум на испорака на предмети во складиштето во Москва");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_SUPPLYQUANTITY","Достапното количество на артикли за нарачка при претстојната испорака до магацинот во Москва.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_STANDART","Стандардни елементи");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_ID","Код за понуда на производи.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_URL","URL-то на страницата со ставка на порталот.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_PRICE","Дилерска цена на артиклот. Секогаш во рубли.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_CURRENCYID","Цената на ставката валута. Секогаш тријте.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_CATEGORYID","ID на категоријата производ.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_PICTURE","Врска до сликата на соодветната понуда на производи.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_TYPEPREFIX","Тип или категорија на производ. Ја зема вредноста <b>недефинирано</b> ако не е поставена.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_MODEL","Модел и важни параметри (на пример, индекс на модел, карактеристики на модификација итн.). Ја зема вредноста <b>недефинирано</b> ако не е поставена.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_SALES_NOTES","Елементот се користи за прикажување информации за:<br> <ul> <li>потребата да се определи времето на испорака кај менаџерот;</li> <li>прекинувањето на купувањето на артиклот (не го доставуваме ставка повеќе).</li> </ul>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_DELIVERY_OPTIONS","Време на испорака <b>за артиклите по барање</b> до магацинот во Москва. Вредноста се испраќа во атрибутот <b>денови</b>. Се прикажува само ако доставата е достапна за предметот.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_WEIGHT","Елементот е дизајниран да ја специфицира тежината на предметот. <b>Тежината е во килограми вклучувајќи го и пакувањето</b>.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_DIMENSIONS","Елементот е дизајниран да ги специфицира димензиите на предметот (должина, ширина, висина) во пакувањето. <b>Димензиите се во сантиметри</b>.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_DELIVERY","Достапност за испорака. Прифаќа вредности:<br> <ul> <li><b>неточно</b> — ние веќе не го испраќаме предметот или треба да го проверите времето на испорака кај менаџерот;</li> <li><b >true</b> — предметот може да се испорача;</li> </ul>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_PICKUP","Достапност за пикап. Прифаќа вредности:<br> <ul> <li><b>неточно</b> — веќе не го доставуваме предметот и нема залиха;</li> <li><b>точно</b > — артикалот е на залиха или е можна испорака на барање, можете да го резервирате избраниот артикл и да го подигнете сами;</li> </ul>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"NON_STANDART","Нестандардни елементи");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_STOCK_CODE","шифра на акции");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_INSTOCK","Количината на артикли достапни за резервација во избраниот магацин.");
