INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_PRICE_CSV","Тековната цена на предметот е прикажана во рубли. Во зависност од избраниот ценовник, цената може да биде или малопродажна или дилерска цена.");
