INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"PRICES_D_LOCAL_DELIVERY_DAYS","Време на испорака на бараните предмети до магацинот во Москва. Прифаќа вредности:<br> <ul> <li><b>број (денови)</b>;</li> <li><b>'not_carry'</b> — веќе не го доставуваме предметот и нема залиха;</li> <li><b>'not_defined'</b> — проверете го времето на испорака кај менаџерот,</li> </ul>");
