INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"GROUP_BRANDMANAGER_TEXT","Имате пристап до делот за пребарување за вашиот бренд. Конкретно за приватни етикети, можете да управувате со каталогот на вашиот бренд на imex.gkrp.local, да ги потврдите правата за преземање датотеки и да го известите водечкиот менаџер за потврдите на корисничкиот портал на вашата страница. Можете исто така да ги видите цените за сите ценовници, вклучувајќи ги и оние за ЕУ.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"GROUP_ZIPMANAGER_TEXT","Имате пристап до прегледување на трансакциите и поврзаните информации поврзани со продажбата на резервни делови, вклучувајќи ги сите поплаки, како и пристап до прегледување на сите ценовници.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"GROUP_QUALITYMANAGER_TEXT","Имате пристап до сите трансакции, побарувања и барања за поплаки.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"GROUP_SENIORZIPMANAGER_TEXT","Можете да гледате трансакции и поврзани информации во врска со продажбата на резервни делови, да се справите со сите поплаки, да пристапите до сите ценовници, да управувате со вработените во вашиот оддел, да испраќате известувања до водечкиот менаџер во врска со корисничките потврди на порталот (ако корисникот е ваш клиент), и регистрира трансакции во име на пандан во насока на продажба на резервни делови.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"GROUP_SENIORQUALITYMANAGER_TEXT","Имате пристап до сите трансакции, поплаки и прашања (дополнувања) поврзани со поплаки. Исто така, можете да ги уредувате вработените во вашиот оддел.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"GROUP_SENIORCOMPLAINTMANAGER_TEXT","Имате пристап до сите трансакции, поплаки и прашања (дополнувања) поврзани со поплаки. Исто така, можете да ги уредувате вработените во вашиот оддел.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"GROUP_COMPLAINTMANAGER_TEXT","Имате пристап до барањата каде што сте назначени како одговорен инженер.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"GROUP_HEADBRANDMANAGER_TEXT","Имате пристап до делот за пребарување за вашиот бренд. Конкретно за приватни етикети, можете да управувате со каталогот на вашиот бренд на imex.gkrp.local, да ги потврдите правата за преземање датотеки и да го известите водечкиот менаџер за потврдите на корисничкиот портал на вашата страница. Можете исто така да ги видите цените за сите ценовници, вклучувајќи ги и оние за ЕУ.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"GROUP_SENIORBRANDMANAGER_TEXT","Имате пристап до делот за пребарување за вашиот бренд. Конкретно за приватни етикети, можете да управувате со каталогот на вашиот бренд на imex.gkrp.local, да ги потврдите правата за преземање датотеки и да го известите водечкиот менаџер за потврдите на корисничкиот портал на вашата страница. Можете исто така да ги видите цените за сите ценовници, вклучувајќи ги и оние за ЕУ.");
