INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"IT_IS_POSSIBLE_TO_PICK_UP_GOODS"," Можете да собирате роба од складиштето Equip само доколку е достапна. Ако треба да соберете стоки од повеќе складишта, прво мора да поднесете барање за пренос за да ја консолидирате стоката во еден склад. Откако сите стоки ќе бидат префрлени во еден магацин, тогаш можете да поднесете до собирањебарање.");
