INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"DEMO_DEACTIVATED","Оваа страница содржи демо податоци. Ве молиме повторно активирајте ја вашата сметка со контактирање на вашиот менаџер.");
