INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"TOOLTIP_EXT_ID","Ве молиме внесете го единствениот број на написот на производот.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"TOOLTIP_NAME","Ве молиме внесете го името на производот за прикажување во каталогот. Имајте предвид дека ако производот веќе постои во каталогот, името може да не се појави. Промената на ова поле ќе бара производот повторно да биде подложен на умереност.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"TOOLTIP_BRAND","Ве молиме внесете го брендот на производот. Ако производот веќе постои во каталогот, брендовите на производите мора да одговараат. Промената на ова поле ќе бара производот повторно да биде подложен на умереност.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"TOOLTIP_CATEGORY","Изберете ја категоријата на производи за прикажување во каталогот. Ако производот веќе постои во каталогот, категориите на производите мора да одговараат. Промената на ова поле ќе бара производот повторно да биде подложен на умереност.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"TOOLTIP_CODE_1C","Се пополнува само доколку таков производ веќе постои во каталогот. Ако не, полето мора да се остави празно.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"TOOLTIP_PRICE","Внесете ја цената на производот без да ја наведете валутата.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"TOOLTIP_CURRENCY","Изберете ја валутата во која е означена цената на производот.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"TOOLTIP_QUANTITY_IN_PACKAGE","Доколку производот се продава во пакување или комплет, ве молиме внесете ја количината на производот во едно пакување. Ако ова поле се остави празно, автоматски ќе се смета како 1 ставка по пакет.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"TOOLTIP_FBS","Внесете ја количината на производот што сакате да го продадете преку системот FBS. Оставете го ова поле празно ако не сакате да продавате производи користејќи го системот FBS.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"TOOLTIP_DELIVERY_TIME","Внесете го бројот на денови што ќе бидат потребни за стоката според нарачката да пристигне во вашиот магацин. Ова ќе го вклучи времето на испорака од вашиот магацин до складиштето Equip кога се пресметува испораката до клиентот. Оставете го ова поле празно ако не сакате да продавате производи по нарачка.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"TOOLTIP_DESCRIPTION","Ве молиме внесете го описот на производот. Имајте предвид дека ако производот веќе постои во каталогот, описот може да не се прикаже на картичката на производот. Промената на ова поле ќе бара производот повторно да биде подложен на умереност.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"TOOLTIP_LENGTH","Внесете ја должината на производот без пакување во милиметри. Промената на ова поле ќе бара производот повторно да биде подложен на умереност.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"TOOLTIP_HEIGHT","Внесете ја висината на производот без пакување во милиметри. Промената на ова поле ќе бара производот повторно да биде подложен на умереност.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"TOOLTIP_WIDTH","Внесете ја ширината на производот без пакување во милиметри. Промената на ова поле ќе бара производот повторно да биде подложен на умереност.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"TOOLTIP_GROSSLENGTH","Внесете ја должината на производот во пакувањето во милиметри. Промената на ова поле ќе бара производот повторно да биде подложен на умереност.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"TOOLTIP_GROSSWIDTH","Внесете ја ширината на производот во пакувањето во милиметри. Промената на ова поле ќе бара производот повторно да биде подложен на умереност.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"TOOLTIP_GROSSHEIGHT","Внесете ја висината на производот во пакувањето во милиметри. Промената на ова поле ќе бара производот повторно да биде подложен на умереност.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"TOOLTIP_WEIGHT","Внесете ја тежината на производот без пакување во килограми. Промената на ова поле ќе бара производот повторно да биде подложен на умереност.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"TOOLTIP_POWER","Внесете ја моќноста на производот во киловати. Промената на ова поле ќе бара производот повторно да биде подложен на умереност.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"TOOLTIP_VOLTAGE","Внесете го напонот на производот во волти. CCПромената на ова поле ќе бара производот повторно да биде подложен на умереност.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"TOOLTIP_WARRANTY","Внесете го гарантниот период за производот во денови. Промената на ова поле ќе бара производот повторно да биде подложен на умереност.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"TOOLTIP_COUNTRY","Внесете ја земјата на производство на производот. Промената на ова поле ќе бара производот повторно да биде подложен на умереност.");
