INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"EXTERNAL_PRODUCT_MODERATION_SUCCESS","Производот на добавувачот е успешно модериран. За да продолжите со модерирање на следниот производ на добавувачот, кликнете на копчето „Следен производ“. За да го затворите прозорецот за модерација, кликнете на „Откажи“");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"EXTERNAL_STOCK_MODERATION_SUCCESS","Магацинот на добавувачот е успешно модериран. За да продолжите со модерирање на следниот склад на добавувачот, кликнете на копчето „Следно складиште“. За да го затворите прозорецот за модерација, кликнете на „Откажи“");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,10,"EXTERNAL_DISCOUNT_MODERATION_SUCCESS","Попустот на добавувачот е успешно модериран. За да продолжите со модерирање на следниот попуст на добавувачот, кликнете на копчето „Следен попуст“. За да го затворите прозорецот за модерација, кликнете на „Откажи“");
